document.addEventListener("DOMContentLoaded",()=>{gsap.registerPlugin(ScrollTrigger);const prefersReducedMotion=window.matchMedia("(prefers-reduced-motion: reduce)").matches;const tl=gsap.timeline({defaults:{ease:"power3.out"}});if(!prefersReducedMotion){tl.to(".hero-tagline",{opacity:1,y:0,duration:1,delay:.5}).to(".hero h1",{opacity:1,y:0,duration:1},"-=0.7").to(".hero-btns",{opacity:1,y:0,duration:1},"-=0.7").to(".stats-bar",{opacity:1,y:0,duration:1},"-=0.5").from(".stat-item",{opacity:0,y:20,stagger:.2,duration:.8},"-=0.5")}const stats=document.querySelectorAll(".stat-number");stats.forEach(stat=>{const target=parseInt(stat.getAttribute("data-target"));const originalText=stat.innerText;let suffix="";if(originalText.includes("MW+"))suffix="MW+";else if(originalText.includes("+"))suffix="+";else if(originalText.includes("k"))suffix="k";const countObj={val:0};gsap.to(countObj,{val:target,duration:4,ease:"power2.out",scrollTrigger:{trigger:stat,start:"top 95%",toggleActions:"play none none none"},onUpdate:()=>{if(suffix==="k"){stat.innerText=Math.ceil(countObj.val/1e3)+"k"}else{stat.innerText=Math.ceil(countObj.val)+suffix}}})});const isMobile=window.innerWidth<=768;const heroCard=document.querySelector(".hero-content-wrapper");if(heroCard&&!isMobile){document.addEventListener("mousemove",e=>{const xAxis=(window.innerWidth/2-e.pageX)/45;const yAxis=(window.innerHeight/2-e.pageY)/45;heroCard.style.transform=`rotateY(${xAxis}deg) rotateX(${yAxis}deg)`});document.addEventListener("mouseleave",()=>{heroCard.style.transform=`rotateY(0deg) rotateX(0deg)`;heroCard.style.transition="all 0.5s ease"});document.addEventListener("mouseenter",()=>{heroCard.style.transition="none"})}const navbar=document.getElementById("navbar");window.addEventListener("scroll",()=>{if(window.scrollY>50){navbar.classList.add("scrolled")}else{navbar.classList.remove("scrolled")}});const hamburger=document.getElementById("hamburger");const mobileMenu=document.getElementById("mobile-menu");if(hamburger&&mobileMenu){hamburger.addEventListener("click",()=>{hamburger.classList.toggle("active");mobileMenu.classList.toggle("active");document.body.style.overflow=mobileMenu.classList.contains("active")?"hidden":""});const mobileLinks=mobileMenu.querySelectorAll("a");mobileLinks.forEach(link=>{link.addEventListener("click",()=>{hamburger.classList.remove("active");mobileMenu.classList.remove("active");document.body.style.overflow=""})});window.addEventListener("resize",()=>{if(window.innerWidth>768){hamburger.classList.remove("active");mobileMenu.classList.remove("active");document.body.style.overflow=""}})}const chatBtn=document.getElementById("chat-btn");const chatWidget=document.getElementById("chat-widget");const chatClose=document.getElementById("chat-close");const chatMessages=document.getElementById("chat-messages");const questionBtns=document.querySelectorAll(".question-btn");const responses={cost:"💰 Cost depends on system size, roof area, and location. A typical 5kW residential system costs ₹3-4 lakhs before subsidies. Want a free quote?",savings:"📊 Most customers save 60-90% on summer bills and 40-70% annually. A 5kW system typically saves ₹50,000-80,000 yearly. You can use our Solar Calculator to get exact estimates for your home!",subsidy:"🎁 Yes! Residential systems get 40% subsidy from Maharashtra govt (MAHAIPL scheme). Plus capital subsidy, tax benefits under 80D, and just 5% GST. We handle all subsidy applications for you!",installation:"⏱️ Installation takes 2-5 days for typical rooftop systems. Total approval + installation is 3-4 weeks including net metering setup. We work fast without compromising on quality!"};if(chatBtn&&chatWidget&&chatClose){chatBtn.addEventListener("click",()=>{chatWidget.classList.toggle("active");if(chatWidget.classList.contains("active")){setTimeout(()=>scrollChatToBottom(),100)}});chatClose.addEventListener("click",()=>{chatWidget.classList.remove("active")});questionBtns.forEach(btn=>{btn.addEventListener("click",function(){const questionKey=this.dataset.question;const questionText=this.innerText.trim();addChatMessage(questionText,"user");setTimeout(()=>{addChatMessage(responses[questionKey],"bot")},500);if(!chatMessages.querySelector(".follow-up-shown")){setTimeout(()=>{addChatMessage("Need more info? Feel free to ask another question or chat with us via WhatsApp/Phone!","bot");addFollowUpOptions()},1500)}})});document.addEventListener("click",e=>{if(!chatWidget.contains(e.target)&&!chatBtn.contains(e.target)){chatWidget.classList.remove("active")}});function addChatMessage(text,sender){const messageDiv=document.createElement("div");messageDiv.className=`chat-message ${sender}-message`;messageDiv.innerHTML=`<p>${text}</p>`;chatMessages.appendChild(messageDiv);scrollChatToBottom()}function addFollowUpOptions(){const followUpDiv=document.createElement("div");followUpDiv.className="follow-up-shown";followUpDiv.style.display="none";chatMessages.appendChild(followUpDiv)}function scrollChatToBottom(){chatMessages.scrollTop=chatMessages.scrollHeight}}document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener("click",function(e){if(this.getAttribute("href").length>1){e.preventDefault();const target=document.querySelector(this.getAttribute("href"));if(target){target.scrollIntoView({behavior:"smooth"})}}})});const revealElements=document.querySelectorAll(".service-card, .section-header, .about-section, .project-card");revealElements.forEach(el=>{if(!prefersReducedMotion){gsap.from(el,{scrollTrigger:{trigger:el,start:"top 85%",toggleActions:"play none none none"},y:50,opacity:0,duration:1,ease:"power3.out"})}});const faqQuestions=document.querySelectorAll(".faq-question");faqQuestions.forEach(button=>{button.addEventListener("click",()=>{const faqItem=button.parentElement;const faqAnswer=faqItem.querySelector(".faq-answer");const icon=button.querySelector("i");const isOpen=faqAnswer.style.display==="block";document.querySelectorAll(".faq-item").forEach(item=>{const answer=item.querySelector(".faq-answer");const btn=item.querySelector(".faq-question");const icn=btn.querySelector("i");if(answer!==faqAnswer){answer.style.display="none";answer.style.maxHeight="0";btn.style.background="white";icn.style.transform="rotate(0deg)"}});if(isOpen){faqAnswer.style.display="none";faqAnswer.style.maxHeight="0";button.style.background="white";icon.style.transform="rotate(0deg)"}else{faqAnswer.style.display="block";faqAnswer.style.maxHeight=faqAnswer.scrollHeight+"px";button.style.background="rgba(46, 125, 50, 0.08)";icon.style.transform="rotate(180deg)"}})});if(!isMobile){document.querySelectorAll(".why-card").forEach(card=>{card.addEventListener("mouseenter",function(){this.style.transform="translateY(-10px)";this.style.boxShadow="0 15px 40px rgba(46, 125, 50, 0.15)"});card.addEventListener("mouseleave",function(){this.style.transform="translateY(0)";this.style.boxShadow="0 8px 25px rgba(0,0,0,0.08)"})})}const monthlyBillInput=document.getElementById("monthlyBill");const monthlyBillRange=document.getElementById("monthlyBillRange");const unitRateInput=document.getElementById("unitRate");const btnShowResults=document.getElementById("btn-show-results");const btnBackToInput=document.getElementById("btn-back-to-input");const step1=document.getElementById("calc-step-1");const step2=document.getElementById("calc-step-2");const dot1=document.getElementById("step1-dot");const dot2=document.getElementById("step2-dot");if(monthlyBillInput&&monthlyBillRange&&unitRateInput&&btnShowResults){const resSystemSize=document.getElementById("resSystemSize");const resSpace=document.getElementById("resSpace");const resMonthlySavings=document.getElementById("resMonthlySavings");const resSystemCost=document.getElementById("resSystemCost");const summaryBill=document.getElementById("summary-bill");function calculateSolar(){let bill=parseFloat(monthlyBillInput.value)||0;let rate=parseFloat(unitRateInput.value)||10;let dailyUnitsRequired=bill/(rate*30);let capacityKw=dailyUnitsRequired/4;if(capacityKw<1&&bill>0)capacityKw=1;let monthlySavings=Math.round(bill*.9);let systemSize=capacityKw.toFixed(1);let spaceRequired=Math.round(capacityKw*100);let cost=Math.round(capacityKw*52e3);resSystemSize.innerText=systemSize;resSpace.innerText=spaceRequired;resMonthlySavings.innerText=monthlySavings.toLocaleString("en-IN");resSystemCost.innerText=cost.toLocaleString("en-IN");summaryBill.innerText=bill.toLocaleString("en-IN")}btnShowResults.addEventListener("click",()=>{calculateSolar();step1.classList.remove("active");step2.classList.add("active");dot1.classList.remove("active");dot2.classList.add("active");window.scrollTo({top:document.getElementById("calculator-section").offsetTop-100,behavior:"smooth"})});btnBackToInput.addEventListener("click",()=>{step2.classList.remove("active");step1.classList.add("active");dot2.classList.remove("active");dot1.classList.add("active")});monthlyBillRange.addEventListener("input",e=>{monthlyBillInput.value=e.target.value});monthlyBillInput.addEventListener("input",e=>{monthlyBillRange.value=e.target.value});calculateSolar()}});